import{_ as o,o as t,c as a,a5 as i}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"LTX director worker implementation plan","description":"","frontmatter":{},"headers":[],"relativePath":"feature/ltx-director-worker/plan.md","filePath":"feature/ltx-director-worker/plan.md"}'),r={name:"feature/ltx-director-worker/plan.md"};function n(d,e,s,c,l,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="ltx-director-worker-implementation-plan" tabindex="-1">LTX director worker implementation plan <a class="header-anchor" href="#ltx-director-worker-implementation-plan" aria-label="Permalink to &quot;LTX director worker implementation plan&quot;">​</a></h1><p>Use Ponytail and writing-plans; execute inline with the executing-plans workflow. Reuse the current image worker&#39;s authenticated transport and media/S3 handling rather than adding another persistence system.</p><ol><li>Refactor <code>ltx-video/build_flow.py</code> into importable <code>build_canvas</code>; preserve its CLI. Package the Qwen subgraph data so the deployed builder does not depend on <code>ovi-video-api</code> on the Windows machine.</li><li>Add GUI-to-API conversion with actual <code>/object_info</code> schemas, promoted subgraph widgets, namespaced IDs, optional input omission and final-output reachability pruning. Test linkage and literal lists separately.</li><li>Add the LTX worker using the existing image worker API pattern. Validate script/mode and image sizes before uploading; validate executable graph before <code>/prompt</code>. Keep status and media authentication.</li><li>Add backend LTX settings/director resources and reuse existing Claude vision call. Extend the existing image worker polling/download helper. Route only configured 20-second image jobs to LTX.</li><li>Add optional character image to Business request and web service/editor. Preserve old Java request constructors and old modes; update <code>vi/editor.json</code> and <code>en/editor.json</code> together.</li><li>Package worker, builder, director, templates and install/start instructions into <code>ltx_video_bundle.zip</code>. Run focused Python/Java checks, frontend CI and a mocked submit/poll/media integration.</li></ol><p>No database migration, scheduler changes, remote render, deployment, commits or unrelated source cleanup are part of this change.</p><h2 id="revision-2026-11-18-vace" tabindex="-1">Revision 2026-11-18 (VACE) <a class="header-anchor" href="#revision-2026-11-18-vace" aria-label="Permalink to &quot;Revision 2026-11-18 (VACE)&quot;">​</a></h2><ol><li>Worker: <code>ltx-video/wan_vace_bundle/vace_api.py</code> (copy of the LTX worker contract, no S3), <code>canvas_api.py</code> copied, <code>start_api.py</code> compiles all VACE flows against live <code>/object_info</code> before starting; <code>setup.sh</code> starts it on 10200, ngrok targets 10200.</li><li>AI service: replace <code>app/resources/ltx/</code> script schema and director prompt with the VACE format; two examples copied from <code>flows/unbox</code> and <code>flows/tvc</code>. <code>ltx_director.py</code> validates timing/panels, sets size, sends the character as <code>extra_images</code>.</li><li>Tests: worker (mock ComfyUI, real canvas compile with a fake schema), director (mock Claude, schema + timing rejection, transport). No web/Business change.</li></ol>',6)])])}const h=o(r,[["render",n]]);export{u as __pageData,h as default};
